#!/usr/bin/env node
// Fails when a commit message carries an AI attribution trailer. AI use is
// disclosed in the pull request body (the "AI usage" section) and nowhere else.
//
//   node scripts/check-commit-messages.mjs <base> <head>   check the commits in base..head
//
// A commit fails if its message contains:
//   - a "Co-Authored-By:" line that names an AI tool or one of its addresses;
//   - "Generated with" (any case), or "Generated by" an AI tool;
//   - a line that starts with the robot emoji.
// A Co-Authored-By naming a person passes.
import { execFileSync } from "node:child_process";
import { pathToFileURL } from "node:url";

const TOOLS = "claude|anthropic|openai|chatgpt|gpt|codex|copilot|gemini|bard|cursor|codebuff|devin|aider|windsurf|cody|tabnine|amazon q|codewhisperer|jetbrains ai|continue\\.dev|replit";
const ADDRESSES = "anthropic\\.com|openai\\.com|codebuff\\.com|cursor\\.com|cursor\\.sh|github\\.com/apps/copilot|copilot@|noreply@(anthropic|openai)";
const RULES = [
  { name: "Co-Authored-By naming an AI tool", test: (line) => /^\s*co-authored-by\s*:/i.test(line) && new RegExp(`\\b(${TOOLS})\\b|${ADDRESSES}`, "i").test(line) },
  { name: "\"Generated with\"", test: (line) => /\bgenerated with\b/i.test(line) },
  { name: "\"Generated by\" an AI tool", test: (line) => new RegExp(`\\bgenerated by\\b.*\\b(${TOOLS})\\b`, "i").test(line) },
  { name: "robot emoji line", test: (line) => /^\s*🤖/u.test(line) },
];

/** Returns [{ line, rule }] for every offending line in a commit message. */
export function findTrailers(message) {
  const found = [];
  for (const line of String(message).split(/\r?\n/)) {
    for (const rule of RULES) if (rule.test(line)) { found.push({ line: line.trim(), rule: rule.name }); break; }
  }
  return found;
}

/** Checks every commit in base..head; returns [{ sha, subject, found }] for the failing ones. */
export function check(base, head, cwd = process.cwd()) {
  const log = execFileSync("git", ["log", "--format=%H%x1f%B%x1e", `${base}..${head}`], { cwd, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
  const bad = [];
  for (const entry of log.split("\x1e")) {
    const [sha, ...rest] = entry.replace(/^\n/, "").split("\x1f");
    if (!sha) continue;
    const message = rest.join("\x1f");
    const found = findTrailers(message);
    if (found.length) bad.push({ sha: sha.trim(), subject: message.split("\n")[0], found });
  }
  return bad;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const [base, head] = process.argv.slice(2);
  if (!base || !head) { console.error("usage: node scripts/check-commit-messages.mjs <base> <head>"); process.exit(2); }
  const bad = check(base, head);
  if (!bad.length) { console.log(`No AI attribution trailers in ${base.slice(0, 8)}..${head.slice(0, 8)}.`); process.exit(0); }
  for (const c of bad) {
    console.error(`${c.sha.slice(0, 8)} ${c.subject}`);
    for (const f of c.found) console.error(`  ${f.rule}: ${f.line}`);
  }
  console.error("\nRemove the trailer from the commit message (git commit --amend, or an interactive rebase) and push again.\nDisclose AI use in the pull request's \"AI usage\" section instead.");
  process.exit(1);
}
